# Validate inputs
if not isinstance(logp_with_result, np.ndarray) or not isinstance(logp_call_only, np.ndarray) or not isinstance(logp_no_call, np.ndarray):
    raise ValueError("Inputs must be numpy arrays")
for arr in [logp_with_result, logp_call_only, logp_no_call]:
    if arr.ndim != 2:
        raise ValueError("Inputs must be 2-dimensional matrices")
    if arr.size == 0:
        raise ValueError("Inputs must not be empty")
    if not np.all(np.isfinite(arr)):
        raise ValueError("Inputs must contain only finite values")
    if np.any(arr > 0):
        raise ValueError("Inputs must be nonpositive")
if logp_with_result.shape != logp_call_only.shape or logp_with_result.shape != logp_no_call.shape:
    raise ValueError("Inputs must have the same shape")
if isinstance(tau_filter, bool):
    raise ValueError("tau_filter must not be a boolean")
if not np.isfinite(tau_filter) or tau_filter < 0:
    raise ValueError("tau_filter must be finite and nonnegative")
# Compute margins
sum_with = np.sum(logp_with_result, axis=1)
sum_call = np.sum(logp_call_only, axis=1)
sum_nocall = np.sum(logp_no_call, axis=1)
max_without = np.maximum(sum_call, sum_nocall)
margin = sum_with - max_without
keep_mask = margin > tau_filter
return keep_mask, margin
